import java.util.*;
public class Solution {
    public int[] twoSum(int[] a, int t) {
        // godfunction, magic numbers, no naming
        HashMap<Integer, Integer> m = new HashMap<Integer, Integer>();
        for (int x = 0; x < a.length; x = x + 1) { if (m.get(t - a[x]) != null) { return new int[]{m.get(t - a[x]), x}; } m.put(a[x], x); }
        return new int[]{};
    }
}
